"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[98589],{42209:e=>{e.exports=JSON.parse('{"label":"low-level developer","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/tags/low-level-developer","allTagsPath":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/tags","count":8,"items":[{"id":"version-0.9/migration-guides/from-08-to-09","title":"Breaking Changes v0.9","description":"This guide is designed to highlight the key distinctions between v0.8 and v0.9, offering assistance to those transitioning an existing application or individuals already acquainted with v0.8 who require a concise overview.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/migration-guides/from-08-to-09"},{"id":"version-0.9/dapp-architecture","title":"dApp architecture","description":"Borrowing from familiar mainstream terminology, from a developer\u2019s point of view a Cartesi dApp is developed by implementing two main components: a front-end and a back-end.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/dapp-architecture"},{"id":"version-0.9/dapp-life-cycle","title":"dApp life cycle","description":"Now that we have described the architecture of a Cartesi dApp and how the front-end and back-end communicate with the Cartesi Rollups framework, let\u2019s step back a bit to discuss how a dApp can be implemented in practice.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/dapp-life-cycle"},{"id":"version-0.9/main-concepts","title":"Main concepts","description":"As explained in the previous section, the Cartesi Rollups framework achieves scalability by moving the bulk of the computation outside the blockchain, using the ledger as a data source but not as an execution environment. As such, the solution contains both on-chain (L1) and off-chain (L2) components.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/main-concepts"},{"id":"version-0.9/http-api","title":"Overview","description":"In a Cartesi dApp, the front-end and back-end parts of the application communicate with each other through the Rollups framework via a set of HTTP APIs.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/http-api"},{"id":"version-0.9/overview","title":"Overview","description":"The combination of an Optimistic Rollups framework and the Cartesi Machine Emulator enables the development of smart contracts and dApps using any package or library that is available for Linux. This allows developers to break free from the scalability limitations of the Ethereum Virtual Machine (EVM), and brings the rise of a new blockchain era to handle real-life and complex use cases.","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/overview"},{"id":"version-0.9/reading-outputs","title":"Reading outputs","description":"In Cartesi Rollups, the outputs include:","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/reading-outputs"},{"id":"version-0.9/sending-requests","title":"Sending requests","description":"In Cartesi Rollups, there are two kinds of requests that can be made to the dApp:","permalink":"/CARTESI-docs2/pr-preview/pr-8/cartesi-rollups/0.9/sending-requests"}]}')}}]);